export const defaults={symbolTheme:'machines',mode:'sketch',balance:0,exposure:0,contrast:1,temperature:0,tint:0,ink:1,grain:1,dark:'#795e4b',light:'#dfff2f',invert:false,symbols:true,grid:36,size:1.15,coverage:100,opacity:100,glyphs:[true,true,true,true],ratio:'original',cropX:50,cropY:50,customW:16,customH:9};
export const clamp=(x,a=0,b=1)=>Math.max(a,Math.min(b,x));
export function normalize(input={}){const p={...defaults,glyphs:[...defaults.glyphs]};for(const k of ['mode','ratio'])if(typeof input[k]==='string')p[k]=input[k];if(!['sketch','duotone'].includes(p.mode))p.mode='sketch';if(!['original','1:1','4:3','3:4','16:9','9:16','custom'].includes(p.ratio))p.ratio='original';for(const [k,min,max] of [['balance',-100,100],['exposure',-2,2],['contrast',.4,2],['temperature',-100,100],['tint',-100,100],['ink',0,2.5],['grain',0,2],['grid',18,100],['size',.5,1.5],['coverage',0,100],['opacity',0,100],['cropX',0,100],['cropY',0,100],['customW',1,100],['customH',1,100]])if(Number.isFinite(input[k]))p[k]=clamp(input[k],min,max);for(const k of ['dark','light'])if(/^#[0-9a-f]{6}$/i.test(input[k]||''))p[k]=input[k];for(const k of ['symbols','invert'])if(typeof input[k]==='boolean')p[k]=input[k];if(Array.isArray(input.glyphs)&&input.glyphs.length===4)p.glyphs=input.glyphs.map(Boolean);if(['main','machines','life','intelligence'].includes(input.symbolTheme))p.symbolTheme=input.symbolTheme;return p;}
export function balanceTone(t,balance){return Math.pow(clamp(t),Math.pow(4,-balance/100));}
export function cropRect(w,h,p){let ratio=p.ratio==='original'?w/h:p.ratio==='custom'?p.customW/p.customH:p.ratio.split(':').reduce((a,b)=>Number(a)/Number(b));let cw=w,ch=h;if(w/h>ratio)cw=h*ratio;else ch=w/ratio;return {x:(w-cw)*p.cropX/100,y:(h-ch)*p.cropY/100,w:cw,h:ch};}
export function hash(c,r){let v=Math.imul(c+1,374761393)^Math.imul(r+1,668265263);v=Math.imul(v^(v>>>13),1274126177);return ((v^(v>>>16))>>>0)/4294967296;}
function blur(src,w,h,sigma){sigma=Math.max(.35,sigma);const rad=Math.ceil(sigma*3),kernel=new Float32Array(rad*2+1);let total=0;for(let k=-rad;k<=rad;k++){kernel[k+rad]=Math.exp(-k*k/(2*sigma*sigma));total+=kernel[k+rad];}for(let k=0;k<kernel.length;k++)kernel[k]/=total;const tmp=new Float32Array(src.length),out=new Float32Array(src.length);for(let y=0;y<h;y++)for(let x=0;x<w;x++){let sum=0;for(let k=-rad;k<=rad;k++)sum+=src[y*w+clamp(x+k,0,w-1)]*kernel[k+rad];tmp[y*w+x]=sum;}for(let y=0;y<h;y++)for(let x=0;x<w;x++){let sum=0;for(let k=-rad;k<=rad;k++)sum+=tmp[clamp(y+k,0,h-1)*w+x]*kernel[k+rad];out[y*w+x]=sum;}return out;}
const rgb=hex=>[1,3,5].map(i=>parseInt(hex.slice(i,i+2),16));
export function render(data,w,h,settings){const p=normalize(settings),n=w*h,scale=w/4003,g=new Float32Array(n),gain=2**p.exposure;for(let i=0;i<n;i++){let r=clamp(data[i*4]/255+p.temperature*.001),b=clamp(data[i*4+2]/255-p.temperature*.001),green=clamp(data[i*4+1]/255-p.tint*.001);g[i]=clamp(((r*.2126+green*.7152+b*.0722)*gain-.5)*p.contrast+.5)*255;}
const coarse=blur(g,w,h,9*scale),fine=blur(g,w,h,1.4*scale),detailBlur=blur(g,w,h,16*scale),detailGray=blur(g,w,h,scale);
let dark=rgb(p.dark),light=rgb(p.light);if(p.invert)[dark,light]=[light,dark];const out=new Uint8ClampedArray(n*4),d=Math.max(1,Math.round(3*scale));
for(let y=0;y<h;y++)for(let x=0;x<w;x++){const i=y*w+x,edge=clamp(Math.hypot(fine[y*w+Math.min(w-1,x+d)]-fine[y*w+Math.max(0,x-d)],fine[Math.min(h-1,y+d)*w+x]-fine[Math.max(0,y-d)*w+x])/75),detail=Math.max(0,(coarse[i]-g[i])/45),tone=clamp((g[i]/255-.07)/.86),xx=x/scale,yy=y/scale;let hv=Math.imul((Math.floor(xx/2)+1)^Math.imul(Math.floor(yy/2)+1,374761393),668265263),noise=((hv^(hv>>>13))>>>0)/4294967295,hatch=(Math.sin((xx+yy*.68)*1.05)+Math.sin((xx*.63-yy)*.9))*.25+.5;let ink=(1-tone)*.30+edge*.75+detail*.55+((noise-.42)*(.12+(1-tone)*.45)+(hatch-.5)*(.10+(1-tone)*.30))*p.grain;let t=balanceTone(p.mode==='sketch'?1-clamp(ink*p.ink):tone,p.balance);for(let k=0;k<3;k++)out[i*4+k]=Math.round(dark[k]+(light[k]-dark[k])*t);out[i*4+3]=255;}
const marks=[],cell=p.grid*scale,enabled=p.glyphs.map((v,i)=>v?i:-1).filter(v=>v>=0);if(p.symbols&&p.coverage>0&&enabled.length){const cols=Math.ceil(w/cell),rows=Math.ceil(h/cell),step=Math.max(1,Math.round(3*scale));for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){let sum=0,sq=0,edge=0,count=0;for(let y=Math.floor(r*cell);y<Math.min(h,(r+1)*cell);y+=step)for(let x=Math.floor(c*cell);x<Math.min(w,(c+1)*cell);x+=step){let i=y*w+x,v=detailGray[i]/255;sum+=v;sq+=v*v;edge+=Math.abs(detailGray[i]-detailBlur[i])/255;count++;}if(!count)continue;const mean=sum/count,sd=Math.sqrt(Math.max(0,sq/count-mean*mean)),activity=clamp(clamp((sd-.012)/.105)*.8+edge/count*3);if(activity<.12||hash(c,r)>activity*.78*p.coverage/100)continue;const t=balanceTone(clamp((mean-.17)/.72),p.balance),isDark=t<.45,strength=isDark?1-t:t;let glyph=activity<.38?0:strength<.58?0:strength<.72?1:strength<.87?2:3;if(!p.glyphs[glyph])glyph=enabled.reduce((a,b)=>Math.abs(b-glyph)<Math.abs(a-glyph)?b:a);const size=cell*(glyph===3?.62:glyph===2?.77:.85)*p.size;marks.push({glyph,x:c*cell+(cell-size)/2,y:r*cell+(cell-size)/2,size,color:isDark?(p.invert?p.dark:p.light):(p.invert?p.light:p.dark)});}}
return {pixels:out,marks};}
